import numpy as np


def embed(C, X):
    return C[X].reshape(X.shape[0], -1)


def embed_backward(dE, X, shape):
    dC = np.zeros(shape)
    dC[X] = dE.reshape(X.shape[0], X.shape[1], -1)
    return dC
